const releaseBudgetReservation = `-- name: ReleaseBudgetReservation :one
WITH locked AS (
  SELECT id, policy_id, period_start, period_end, task_id, estimate_usd_ticks, actual_usd_ticks, state, idempotency_key, created_at, finalized_at FROM budget_reservation
  WHERE budget_reservation.id = $1
    AND budget_reservation.state = 'reserved'
  FOR UPDATE
), changed AS (
  UPDATE budget_reservation AS reservation
  SET state = 'released', finalized_at = now()
  FROM locked
  WHERE reservation.id = locked.id
  RETURNING locked.policy_id, locked.period_start, locked.period_end, locked.estimate_usd_ticks
)
UPDATE budget_period AS period
SET reserved_usd_ticks = GREATEST(0, reserved_usd_ticks - changed.estimate_usd_ticks),
    updated_at = now()
FROM changed
WHERE period.policy_id = changed.policy_id
  AND period.period_start = changed.period_start
  AND period.period_end = changed.period_end
RETURNING period.policy_id, period.period_start, period.period_end, period.spent_usd_ticks, period.reserved_usd_ticks, period.warn_notified_at, period.block_notified_at, period.created_at, period.updated_at
`

func (q *Queries) ReleaseBudgetReservation(ctx context.Context, reservationID pgtype.UUID) (BudgetPeriod, error) {
	row := q.db.QueryRow(ctx, releaseBudgetReservation, reservationID)
	var i BudgetPeriod
	err := row.Scan(
		&i.PolicyID,
		&i.PeriodStart,
		&i.PeriodEnd,
		&i.SpentUsdTicks,
		&i.ReservedUsdTicks,
		&i.WarnNotifiedAt,
		&i.BlockNotifiedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

